CREATE DEFINER=`root`@`localhost` PROCEDURE `setAvailabilityNull`()
BEGIN
	INSERT INTO availability (course_id, c_category, c_num)
    SELECT c.course_id, category, course_num
    FROM courses c
    LEFT JOIN availability a ON c.course_id = a.course_id
    WHERE a.course_id IS NULL;
	END ;;
DELIMITER ;
