/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `UpdateAvailabilityFrequencies`()
BEGIN
    UPDATE availability a
    JOIN (
        SELECT
            course_id,
            (SUM(Spring_2015) + SUM(Spring_2016) + SUM(Spring_2017) + SUM(Spring_2018) + SUM(Spring_2019)
            + SUM(Spring_2020) + SUM(Spring_2021) + SUM(Spring_2022) + SUM(Spring_2023)
            + SUM(Spring_2024) + SUM(Spring_2025))
            / (COUNT(Spring_2015) + COUNT(Spring_2016) + COUNT(Spring_2017) + COUNT(Spring_2018) + COUNT(Spring_2019)
            + COUNT(Spring_2020) + COUNT(Spring_2021) + COUNT(Spring_2022) + COUNT(Spring_2023)
            + COUNT(Spring_2024) + COUNT(Spring_2025)) AS spring_frequency,

            (SUM(Summer_2015) + SUM(Summer_2016) + SUM(Summer_2017) + SUM(Summer_2018) + SUM(Summer_2019)
            + SUM(Summer_2020) + SUM(Summer_2021) + SUM(Summer_2022) + SUM(Summer_2023) + SUM(Summer_2024))
            /  (COUNT(Summer_2015) + COUNT(Summer_2016) + COUNT(Summer_2017) + COUNT(Summer_2018)
            + COUNT(Summer_2019) + COUNT(Summer_2020) + COUNT(Summer_2021) + COUNT(Summer_2022)
            + COUNT(Summer_2023) + COUNT(Summer_2024)) AS summer_frequency,

            (SUM(Fall_2015) + SUM(Fall_2016) + SUM(Fall_2017) + SUM(Fall_2018) + SUM(Fall_2019)
            + SUM(Fall_2020) + SUM(Fall_2021) + SUM(Fall_2022) + SUM(Fall_2023) + SUM(Fall_2024))
            /  (COUNT(Fall_2015) + COUNT(Fall_2016) + COUNT(Fall_2017) + COUNT(Fall_2018)
            + COUNT(Fall_2019) + COUNT(Fall_2020) + COUNT(Fall_2021) + COUNT(Fall_2022)
            + COUNT(Fall_2023) + COUNT(Fall_2024)) AS fall_frequency,

            (SUM(Winter_2017) + SUM(Winter_2018) + SUM(Winter_2020) + SUM(Winter_2021)
            + SUM(Winter_2022) + SUM(Winter_2023) + SUM(Winter_2024))
            /  (COUNT(Winter_2017) + COUNT(Winter_2018)+ COUNT(Winter_2020) + COUNT(Winter_2021)
            + COUNT(Winter_2022) + COUNT(Winter_2023) + COUNT(Winter_2024)) AS winter_frequency
        FROM availability
        WHERE course_id IS NOT NULL
        GROUP BY course_id
    ) subquery
    ON a.course_id = subquery.course_id
    SET
        a.Spring_Frequency = subquery.spring_frequency,
        a.Summer_Frequency = subquery.summer_frequency,
        a.Fall_Frequency = subquery.fall_frequency,
        a.Winter_Frequency = subquery.winter_frequency;
END ;;
DELIMITER ;
